/* Linear fit through the two chart points bracketing x — matches the
   workbook's FORECAST(x, OFFSET(knownY, MATCH(x,knownX,1)-1,0,2), ...) */
function interp(pts, x, xi = 0, yi = 1) {
  const n = pts.length;
  let idx = 0;
  for (let i = 0; i < n; i++) if (pts[i][xi] <= x) idx = i;
  if (idx >= n - 1) idx = n - 2;
  let a = pts[idx], b = pts[idx + 1], j = idx;
  while (a[xi] === b[xi] && j > 0) { j--; a = pts[j]; b = pts[j + 1]; }
  j = idx;
  while (a[xi] === b[xi] && j + 2 < n) { j++; a = pts[j]; b = pts[j + 1]; }
  if (a[xi] === b[xi]) return a[yi];
  return a[yi] + ((x - a[xi]) * (b[yi] - a[yi])) / (b[xi] - a[xi]);
}

const INLETS = [
  { id: "basic", label: "Basic / AFS" },
  { id: "ps", label: "Particle separator" },
];

// which digitised chart set serves each combination. The snow deflector kit
// supplement governs whatever inlet is fitted underneath it.
const VARIANT = {
  basic: { off: "basic", on: "psb" },
  ps: { off: "ps", on: "psb" },
};
